"""Writes textedit/catalog.json. Local only."""
import json
M = "Verified on macOS 15.6.1 only, so it isn't known to work on macOS 26 or any other version."
ROOT = "Only touches what TEXTEDIT_ALLOWED_ROOT allows if it is set; if it isn't set, any .txt or .rtf file you can reach is accepted."
EN = "UI mode depends on English names and was tested only in English."
